// Package templates renders the filehttp example's UI: templ-generated page
// components plus small formatting helpers | templates 渲染 filehttp 示例的界面：
// templ 生成的页面组件加少量格式化辅助函数.
//
// # Notes | 说明
//
// files_templ.go and layout_templ.go are generated by templ — edit the
// .templ sources and regenerate, not these files. helpers.go is the only
// hand-written file here, holding the size and hash formatting the
// templates use.
// files_templ.go 与 layout_templ.go 由 templ 生成——请修改 .templ 源文件后重新
// 生成，不要手改这些文件。helpers.go 是本包唯一手写文件，存放模板用到的
// 大小与哈希格式化函数。
package templates

import "fmt"

func humanSize(n int64) string {
	if n < 1024 {
		return fmt.Sprintf("%d B", n)
	}
	units := []string{"KB", "MB", "GB", "TB"}
	value := float64(n)
	unit := "B"
	for _, u := range units {
		value /= 1024
		unit = u
		if value < 1024 {
			break
		}
	}
	return fmt.Sprintf("%.1f %s", value, unit)
}

func shortHash(hash string) string {
	if len(hash) <= 10 {
		return hash
	}
	return hash[:10]
}
